style.css:
@-moz-document domain("youtube.com") {
html, body {
    background: url("https://i.pinimg.com/1200x/36/09/7d/36097d10c54d49a96a355ce098c7180a.jpg") 
                no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Transparent backgrounds for main containers */
  ytd-app, ytd-page-manager, ytd-watch-flexy, #columns, #primary, #secondary {
    background: transparent !important;
  }

  /* Top navigation bar */
  #masthead-container {
    background: rgba(0, 0, 0, 0.6) !important; /* semi-transparent black */
    backdrop-filter: blur(8px) !important;     /* frosted glass effect */
    border-bottom: 1px solid rgba(255,255,255,0.2) !important;
  }

  /* Search bar container */
  #search-form, ytd-searchbox {
    background: rgba(255, 255, 255, 0.15) !important;
    border-radius: 10px !important;
    padding: 4px !important;
    backdrop-filter: blur(4px) !important;
  }

  /* Search input text */
  input#search {
    color: #fff !important;
    font-weight: bold !important;
  }

  /* Search button */
  #search-icon-legacy {
    background: rgba(255, 255, 255, 0.25) !important;
    border-radius: 6px !important;
  }

  /* Hover effect for search bar */
  #search-form:hover, ytd-searchbox:hover {
    background: rgba(255, 255, 255, 0.3) !important;
    box-shadow: 0 0 8px rgba(255,255,255,0.5) !important;
  }
}
